"""bighead — 侧面大特写（分面平涂，像矢量切面）。单位：头高 = 1，头心在原点，朝 +x。"""
import math, cairo
def mix(a, b, k): return tuple(a[i] * (1 - k) + b[i] * k for i in range(3))

def ned(c, cx, cy, hh, face=1, skin=(0.66, 0.50, 0.40), lite=(0.90, 0.68, 0.48), shade=(0.40, 0.27, 0.23), deep=(0.20, 0.13, 0.13),
        hair=(0.17, 0.12, 0.10), hair_l=(0.36, 0.25, 0.18), beard=(0.19, 0.14, 0.12), beard_l=(0.44, 0.33, 0.25), cloth=(0.15, 0.13, 0.13), cloth_l=(0.30, 0.25, 0.22), closed=0.0, tear=0.0):
    c.save(); c.translate(cx, cy); c.scale(face * hh, hh)
    def P(pts, col, a=1.0): c.set_source_rgba(*col, a); c.move_to(*pts[0]); [c.line_to(*p) for p in pts[1:]]; c.close_path(); c.fill()
    def L(pts, col, w, a=1.0): c.set_source_rgba(*col, a); c.set_line_width(w); c.set_line_cap(cairo.LINE_CAP_ROUND); c.set_line_join(cairo.LINE_JOIN_ROUND); c.move_to(*pts[0]); [c.line_to(*p) for p in pts[1:]]; c.stroke()
    # 后发
    P([(-0.10, -0.52), (-0.38, -0.47), (-0.55, -0.25), (-0.60, 0.05), (-0.58, 0.35), (-0.63, 0.60), (-0.53, 0.80), (-0.42, 0.70), (-0.31, 0.84), (-0.19, 0.66), (-0.10, 0.45), (-0.05, 0.10)], hair)
    # 肩、囚衣
    P([(-0.62, 0.78), (-0.30, 0.70), (0.16, 0.84), (0.44, 1.00), (0.66, 1.28), (0.78, 2.1), (-1.5, 2.1), (-1.35, 1.25), (-0.98, 0.96)], cloth)
    P([(0.16, 0.84), (0.44, 1.00), (0.66, 1.28), (0.78, 2.1), (0.62, 2.1), (0.52, 1.36), (0.34, 1.08), (0.10, 0.93)], cloth_l)
    P([(-0.30, 0.70), (0.16, 0.84), (0.10, 0.93), (-0.12, 0.98), (-0.40, 0.84)], mix(cloth, cloth_l, 0.45))
    # 脖子
    P([(-0.27, 0.20), (0.10, 0.40), (0.15, 0.72), (0.16, 0.84), (-0.30, 0.74), (-0.36, 0.5)], mix(shade, deep, 0.55))
    P([(0.02, 0.42), (0.10, 0.40), (0.15, 0.72), (0.16, 0.84), (0.06, 0.80)], mix(shade, skin, 0.25))
    # 脸
    prof = [(0.00, -0.50), (0.25, -0.44), (0.34, -0.30), (0.365, -0.18), (0.395, -0.115), (0.35, -0.045), (0.42, 0.03), (0.495, 0.095), (0.47, 0.135), (0.385, 0.155), (0.40, 0.20), (0.425, 0.225), (0.375, 0.25),
            (0.41, 0.275), (0.395, 0.305), (0.36, 0.335), (0.39, 0.40), (0.365, 0.455), (0.28, 0.495), (0.05, 0.43), (-0.115, 0.30), (-0.30, 0.24), (-0.46, 0.05), (-0.48, -0.20), (-0.36, -0.42), (-0.15, -0.50)]
    P(prof, skin)
    P([(0.05, -0.02), (0.20, -0.115), (0.22, -0.26), (0.05, -0.30), (-0.05, -0.12)], mix(skin, shade, 0.55))                          # 太阳穴
    P([(0.22, -0.02), (0.25, 0.05), (0.30, 0.16), (0.20, 0.24), (0.02, 0.20), (-0.07, 0.05), (0.05, -0.02)], mix(skin, shade, 0.70))   # 颧下
    P([(0.25, -0.44), (0.34, -0.30), (0.365, -0.18), (0.395, -0.115), (0.30, -0.145), (0.25, -0.28), (0.19, -0.42)], lite)           # 额头亮面
    P([(0.22, -0.02), (0.33, -0.01), (0.27, 0.055), (0.12, 0.06)], mix(skin, lite, 0.55))                                           # 颧骨
    P([(0.20, -0.118), (0.39, -0.108), (0.35, -0.045), (0.33, -0.008), (0.215, -0.018)], deep)                                      # 眼窝
    P([(0.33, -0.008), (0.385, 0.045), (0.375, 0.155), (0.30, 0.16), (0.26, 0.055)], shade)                                         # 鼻侧
    P([(0.35, -0.045), (0.42, 0.03), (0.495, 0.095), (0.47, 0.135), (0.435, 0.105), (0.385, 0.045)], lite)                          # 鼻梁
    P([(0.47, 0.135), (0.385, 0.155), (0.375, 0.13), (0.435, 0.105)], deep)                                                         # 鼻底
    # 眼：closed 0→1 上眼皮落下、眉头压低；tear 0→1 一滴泪先在内眼角聚起（0–0.15），再顺着鼻侧滑到胡须
    k = min(1.0, max(0.0, closed)); lerp = lambda p, q: (p[0] + (q[0] - p[0]) * k, p[1] + (q[1] - p[1]) * k)
    P([(0.250, -0.070), (0.335, -0.074), (0.338, -0.050), (0.262, -0.046)], (0.80, 0.74, 0.66))
    c.set_source_rgb(0.10, 0.09, 0.10); c.arc(0.318, -0.061, 0.016, 0, math.tau); c.fill()
    lash = [lerp(p, q) for p, q in zip([(0.225, -0.066), (0.29, -0.080), (0.348, -0.078)], [(0.226, -0.050), (0.29, -0.038), (0.346, -0.046)])]
    if k > 0:
        P([(0.220, -0.074), (0.29, -0.090), (0.352, -0.086)] + lash[::-1], mix(deep, shade, 0.30 + 0.25 * k))                           # 眼皮
        L([(0.235, -0.074 + 0.012 * k), (0.29, -0.086 + 0.020 * k), (0.340, -0.082 + 0.014 * k)], mix(shade, skin, 0.5), 0.006, 0.55 * k)   # 眼皮上一道受光
    L(lash, (0.05, 0.03, 0.03), 0.014)
    L([(0.24, -0.030), (0.30, -0.022), (0.335, -0.030)], mix(deep, shade, 0.5), 0.008, 0.9); L([(0.20, -0.005), (0.27, 0.012)], shade, 0.007, 0.8)
    if k > 0: L([(0.205, -0.060), (0.185, -0.072)], shade, 0.006, 0.7 * k); L([(0.203, -0.046), (0.180, -0.044)], shade, 0.006, 0.7 * k)       # 眼角挤出的纹
    d = 0.016 * k; P([(0.13, -0.150), (0.29, -0.172 + d * 0.6), (0.405, -0.128 + d), (0.392, -0.100 + d), (0.28, -0.128 + d * 0.6), (0.15, -0.112)], hair)   # 眉
    if tear > 0:
        path = [(0.338, -0.040), (0.336, -0.012), (0.326, 0.030), (0.318, 0.075), (0.322, 0.120), (0.316, 0.160)]; wet = (1.0, 0.90, 0.72)
        well = min(1.0, tear / 0.15); u = max(0.0, (tear - 0.15) / 0.85) * (len(path) - 1); i = min(int(u), len(path) - 2); f = u - i
        tx, ty = path[i][0] + (path[i + 1][0] - path[i][0]) * f, path[i][1] + (path[i + 1][1] - path[i][1]) * f
        L([(0.300, -0.038), (0.340, -0.042)], wet, 0.005, 0.55 * well)                                                                 # 睫毛下的水光
        if u > 0: L(path[:i + 1] + [(tx, ty)], wet, 0.0045, 0.38)                                                                      # 泪痕
        r = 0.0115 * (0.5 + 0.5 * well); c.set_source_rgba(*wet, 0.95); c.move_to(tx, ty - r * 2.3); c.curve_to(tx + r * 1.2, ty - r * 0.6, tx + r, ty + r, tx, ty + r); c.curve_to(tx - r, ty + r, tx - r * 1.2, ty - r * 0.6, tx, ty - r * 2.3); c.fill()
        c.set_source_rgba(1, 1, 1, 0.95); c.arc(tx + r * 0.25, ty + r * 0.15, r * 0.36, 0, math.tau); c.fill()
    L([(0.22, -0.30), (0.33, -0.27)], shade, 0.007, 0.7); L([(0.20, -0.235), (0.345, -0.215)], shade, 0.007, 0.7)                    # 抬头纹
    # 耳
    c.save(); c.translate(-0.085, 0.035); c.scale(0.062, 0.105); c.set_source_rgb(*mix(skin, lite, 0.25)); c.arc(0, 0, 1, 0, math.tau); c.fill(); c.set_source_rgb(*shade); c.arc(0.1, -0.05, 0.55, 0, math.tau); c.fill(); c.restore()
    # 胡须
    bd = [(-0.05, 0.07), (0.03, 0.10), (0.14, 0.17), (0.28, 0.20), (0.385, 0.165), (0.44, 0.20), (0.458, 0.245), (0.405, 0.262), (0.44, 0.30), (0.447, 0.40), (0.425, 0.50), (0.37, 0.56), (0.335, 0.60),
          (0.27, 0.575), (0.20, 0.615), (0.12, 0.555), (0.06, 0.55), (-0.07, 0.42), (-0.155, 0.28), (-0.125, 0.12)]
    P(bd, beard)
    P([(0.385, 0.165), (0.44, 0.20), (0.458, 0.245), (0.405, 0.262), (0.44, 0.30), (0.447, 0.40), (0.425, 0.50), (0.37, 0.56), (0.335, 0.60), (0.345, 0.46), (0.365, 0.31), (0.335, 0.225)], beard_l)
    P([(0.335, 0.60), (0.27, 0.575), (0.30, 0.44), (0.345, 0.46)], mix(beard, beard_l, 0.5))
    P([(0.14, 0.17), (0.28, 0.20), (0.335, 0.225), (0.30, 0.29), (0.16, 0.24)], mix(beard, beard_l, 0.30))
    for (x0, y0, x1, y1) in ((0.30, 0.34, 0.275, 0.50), (0.24, 0.30, 0.20, 0.52), (0.16, 0.30, 0.10, 0.48), (0.39, 0.33, 0.385, 0.50), (0.05, 0.22, -0.03, 0.38)): L([(x0, y0), (x1, y1)], (0.55, 0.50, 0.45), 0.006, 0.55)
    L([(0.335, 0.262), (0.415, 0.262)], (0.05, 0.03, 0.03), 0.010)
    # 前发
    P([(0.30, -0.36), (0.25, -0.50), (0.05, -0.575), (-0.20, -0.565), (-0.42, -0.45), (-0.56, -0.22), (-0.59, 0.05), (-0.51, 0.30), (-0.41, 0.46), (-0.29, 0.51), (-0.165, 0.42), (-0.10, 0.25), (-0.13, 0.10),
       (-0.05, 0.07), (-0.02, -0.08), (0.10, -0.20), (0.20, -0.27)], hair)
    P([(0.27, -0.43), (0.05, -0.53), (-0.20, -0.51), (-0.37, -0.39), (-0.21, -0.465), (0.04, -0.475), (0.22, -0.395)], hair_l)
    P([(0.14, -0.31), (-0.10, -0.37), (-0.34, -0.21), (-0.45, 0.06), (-0.37, -0.13), (-0.12, -0.31), (0.10, -0.265)], hair_l, 0.8)
    P([(-0.20, -0.10), (-0.38, 0.12), (-0.40, 0.36), (-0.33, 0.20), (-0.19, 0.00)], hair_l, 0.6)
    for pts in ([(0.29, -0.37), (0.40, -0.26), (0.415, -0.16), (0.40, -0.05)], [(0.24, -0.40), (0.33, -0.30), (0.35, -0.20)], [(-0.02, -0.06), (0.02, 0.06), (0.00, 0.16)]): L(pts, hair, 0.012)
    c.restore()
